**interface Product**

Write an interface `Product` with `id` and `name` (strings), `price` (number) and an optional numeric `discount`, then type `finalPrice` with it.

```ts
// TODO: interface Product { ... }

function finalPrice(product) {
  const discount = product.discount ?? 0;
  return product.price * (1 - discount);
}
```

notes.back:
// Why: `discount?: number` means the property may be missing, so its type inside the
// function is number | undefined — which is why `?? 0` is needed.
// Docs: https://www.typescriptlang.org/docs/handbook/2/objects.html
interface Product {
  id: string;
  name: string;
  price: number;
  discount?: number;
}

function finalPrice(product: Product): number {
  const discount = product.discount ?? 0;
  return product.price * (1 - discount);
}

